use crate::finder_errors::FinderError;
use crate::password_gen::password_generator_count;
use crate::password_mask::{ParsedMask, mask_password_count};
use crate::password_reader::password_reader_count;
use crate::password_worker::password_checker;
use crate::zip_utils::validate_zip;
use crate::{GenPasswords, MaskGenPasswords, PasswordFile};
use indicatif::{ProgressBar, ProgressDrawTarget, ProgressStyle};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::{Receiver, SyncSender, sync_channel};
use zip_password_finder::password_gen::password_count_already_generated;

#[derive(Clone, Debug)]
pub enum Strategy {
    PasswordFile(PathBuf),
    GenPasswords {
        charset: Vec<char>,
        min_password_len: usize,
        max_password_len: usize,
        starting_password: Option<String>,
    },
    MaskGenPasswords {
        mask: ParsedMask,
    },
}

pub fn password_finder(
    zip_path: &str,
    workers: usize,
    file_number: usize,
    strategy: &Strategy,
    stop_signal: Arc<AtomicBool>,
) -> Result<Option<String>, FinderError> {
    let file_path = Path::new(zip_path);

    // Progress bar
    let progress_bar = ProgressBar::new(0);
    let progress_style = ProgressStyle::default_bar()
        .template("[{elapsed_precise}] {wide_bar} {pos}/{len} throughput:{per_sec} (eta:{eta})")
        .expect("Failed to create progress style");
    progress_bar.set_style(progress_style);
    // Refresh terminal 2 times per seconds
    let draw_target = ProgressDrawTarget::stdout_with_hz(2);
    progress_bar.set_draw_target(draw_target);

    // Fail early if the zip file is not valid
    let validated_zip = validate_zip(file_path, file_number)?;
    let file_number = validated_zip.file_number;
    match &validated_zip.file_name {
        Some(file_name) => {
            progress_bar.println(format!("Targeting file '{file_name}' within the archive"));
        }
        None => progress_bar.println(format!(
            "Cannot get file name from archive for --fileNumber {file_number}"
        )),
    }

    let aes_info = validated_zip.aes_info;
    match &aes_info {
        Some(aes_info) => progress_bar.println(format!(
            "Archive encrypted with AES{} - expect a long wait time",
            aes_info.aes_key_length * 8
        )),
        None => progress_bar
            .println("Archive encrypted with ZipCrypto - expect a much faster throughput"),
    }

    let (send_found_password, receive_found_password): (SyncSender<String>, Receiver<String>) =
        sync_channel(1);

    let (total_password_count, skipped) = match strategy {
        GenPasswords {
            charset,
            min_password_len,
            max_password_len,
            starting_password,
        } => {
            let mut skip = 0;
            let total =
                password_generator_count(charset.len(), *min_password_len, *max_password_len);
            if let Some(starting_password) = starting_password {
                skip =
                    password_count_already_generated(charset, *min_password_len, starting_password);
            }
            (total, skip)
        }
        PasswordFile(password_list_path) => {
            let total = password_reader_count(password_list_path.clone())?;
            progress_bar.println(format!(
                "Using passwords dictionary {password_list_path:?} with {total} candidates."
            ));
            (total, 0)
        }
        MaskGenPasswords { mask } => {
            let total = mask_password_count(mask);
            progress_bar.println(format!("Using mask attack with {total} candidates."));
            (total, 0)
        }
    };

    // set progress bar length according to the total number of passwords
    progress_bar.set_length(total_password_count as u64);
    // set progress bar position according to the number password skipped
    progress_bar.set_position(skipped as u64);
    // reset progress_bar speed
    progress_bar.reset_elapsed();

    let mut worker_handles = Vec::with_capacity(workers);

    progress_bar.println(format!("Starting {workers} workers to test passwords"));
    for i in 1..=workers {
        let join_handle = password_checker(
            i,
            workers,
            file_path,
            file_number,
            aes_info.clone(),
            strategy.clone(),
            send_found_password.clone(),
            stop_signal.clone(),
            progress_bar.clone(),
        );
        worker_handles.push(join_handle);
    }

    // drop reference in `main` so that it disappears completely with workers for a clean shutdown
    drop(send_found_password);

    // wait for password to be found
    if let Ok(password_found) = receive_found_password.recv() {
        // stop workers on success
        stop_signal.store(true, Ordering::Relaxed);
        for h in worker_handles {
            h.join().unwrap();
        }
        progress_bar.finish_and_clear();
        Ok(Some(password_found))
    } else {
        // workers are stopped by the signal
        progress_bar.finish_and_clear();
        Ok(None)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::charsets;
    use crate::password_mask::parse_mask;

    fn find_password_gen(
        path: &str,
        max_password_len: usize,
    ) -> Result<Option<String>, FinderError> {
        find_password_gen_with_file_number(path, max_password_len, 0)
    }

    fn find_password_gen_with_file_number(
        path: &str,
        max_password_len: usize,
        file_number: usize,
    ) -> Result<Option<String>, FinderError> {
        let strategy = GenPasswords {
            charset: charsets::preset_to_charset("l")?,
            min_password_len: 1,
            max_password_len,
            starting_password: None,
        };
        let workers = num_cpus::get_physical();
        password_finder(
            path,
            workers,
            file_number,
            &strategy,
            Arc::new(AtomicBool::new(false)),
        )
    }

    fn find_password_dictionary(path: &str) -> Result<Option<String>, FinderError> {
        let strategy = PasswordFile(PathBuf::from(
            "test-files/generated-passwords-lowercase.txt",
        ));
        let workers = num_cpus::get_physical();
        let file_number = 0;
        password_finder(
            path,
            workers,
            file_number,
            &strategy,
            Arc::new(AtomicBool::new(false)),
        )
    }

    #[test]
    fn find_two_letters_password_generated() {
        let password = find_password_gen("test-files/2.test.txt.zip", 2)
            .unwrap()
            .unwrap();
        assert_eq!(password, "ab");
    }

    #[test]
    fn find_two_letters_password_dictionary() {
        let password = find_password_dictionary("test-files/2.test.txt.zip")
            .unwrap()
            .unwrap();
        assert_eq!(password, "ab");
    }

    #[test]
    fn fail_to_find_two_letters_password_generated() {
        // because max_password_len is 1
        let password = find_password_gen("test-files/2.test.txt.zip", 1).unwrap();
        assert!(password.is_none());
    }

    #[test]
    fn find_three_letters_password_generated() {
        let password = find_password_gen("test-files/3.test.txt.zip", 3)
            .unwrap()
            .unwrap();
        assert_eq!(password, "abc");
    }

    #[test]
    fn find_three_letters_password_dictionary() {
        let password = find_password_dictionary("test-files/3.test.txt.zip")
            .unwrap()
            .unwrap();
        assert_eq!(password, "abc");
    }

    #[test]
    fn fail_to_find_three_letters_password_generated() {
        // because max_password_len is 2
        let password = find_password_gen("test-files/3.test.txt.zip", 2).unwrap();
        assert!(password.is_none());
    }

    #[test]
    fn find_four_letters_password_generated() {
        let password = find_password_gen("test-files/4.test.txt.zip", 4)
            .unwrap()
            .unwrap();
        assert_eq!(password, "abcd");
    }

    #[test]
    fn find_password_multi_file_auto_detect() {
        // index 0 is an unencrypted directory, auto-detection finds the encrypted file at index 1
        let password =
            find_password_gen_with_file_number("test-files/multi-file-with-dir.zip", 2, 0)
                .unwrap()
                .unwrap();
        assert_eq!(password, "ab");
    }

    #[test]
    fn find_password_multi_file_explicit_file_number() {
        // explicitly selecting index 1 (the encrypted file)
        let password =
            find_password_gen_with_file_number("test-files/multi-file-with-dir.zip", 2, 1)
                .unwrap()
                .unwrap();
        assert_eq!(password, "ab");
    }

    #[test]
    fn find_password_multi_file_out_of_range_index() {
        // out-of-range index should auto-detect the first encrypted file
        let password =
            find_password_gen_with_file_number("test-files/multi-file-with-dir.zip", 2, 99)
                .unwrap()
                .unwrap();
        assert_eq!(password, "ab");
    }

    fn find_password_mask(path: &str, mask_pattern: &str) -> Result<Option<String>, FinderError> {
        let no_custom = [None, None, None, None];
        let mask = parse_mask(mask_pattern, &no_custom)?;
        let strategy = MaskGenPasswords { mask };
        let workers = num_cpus::get_physical();
        let file_number = 0;
        password_finder(
            path,
            workers,
            file_number,
            &strategy,
            Arc::new(AtomicBool::new(false)),
        )
    }

    #[test]
    fn find_two_letters_password_mask() {
        let password = find_password_mask("test-files/2.test.txt.zip", "?l?l")
            .unwrap()
            .unwrap();
        assert_eq!(password, "ab");
    }

    #[test]
    fn find_three_letters_password_mask() {
        let password = find_password_mask("test-files/3.test.txt.zip", "?l?l?l")
            .unwrap()
            .unwrap();
        assert_eq!(password, "abc");
    }

    #[test]
    fn find_password_mask_with_literal_prefix() {
        // password is "ab", use mask "a?l" to find it with a literal 'a' prefix
        let password = find_password_mask("test-files/2.test.txt.zip", "a?l")
            .unwrap()
            .unwrap();
        assert_eq!(password, "ab");
    }

    #[test]
    fn fail_to_find_password_mask_wrong_pattern() {
        // password is "ab" but mask only generates digits
        let password = find_password_mask("test-files/2.test.txt.zip", "?d?d").unwrap();
        assert!(password.is_none());
    }
}

