    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = self.total_to_generate - self.generated_count;
        (remaining, Some(remaining))
    }
}

pub fn password_generator_iter(
    charset: Vec<char>,
    min_size: usize,
    max_size: usize,
    starting_password: Option<String>,
