        progress_bar.println(format!(
            "Generating passwords with length from {} to {} for charset with length {}\n{}",
            min_size,
            max_size,
            charset.len(),
            charset.iter().collect::<String>()
        ));
    }
    PasswordGenerator::new(charset, min_size, max_size, starting_password, progress_bar)
}

